import{_ as r,y as s,a as n,o as i,a2 as e,D as h}from"./chunks/framework.DCcmcJcL.js";const f=JSON.parse('{"title":"Shipping Methods","description":"","frontmatter":{},"headers":[],"relativePath":"shipping-method/shipping-methods.md","filePath":"shipping-method/shipping-methods.md","lastUpdated":1789395222000}'),a={name:"shipping-method/shipping-methods.md"};function d(p,t,g,l,c,m){const o=s("ImagePopup");return i(),n("div",null,[t[0]||(t[0]=e('<h1 id="shipping-methods" tabindex="-1">Shipping Methods <a class="header-anchor" href="#shipping-methods" aria-label="Permalink to &quot;Shipping Methods&quot;">​</a></h1><p>Bagisto comes with two shipping methods, <strong>Free Shipping</strong> and <strong>Flat Rate Shipping</strong>. At checkout, shoppers choose from the methods you turn on.</p><h2 id="offer-a-shipping-method" tabindex="-1">Offer a shipping method <a class="header-anchor" href="#offer-a-shipping-method" aria-label="Permalink to &quot;Offer a shipping method&quot;">​</a></h2><ol><li>Go to <strong>Configure &gt;&gt; Sales &gt;&gt; Shipping Methods</strong>.</li><li>In the section of the method you want to offer, switch <strong>Status</strong> on.</li><li>Enter the <strong>Title</strong> shoppers see at checkout.</li><li>Optionally, enter a <strong>Description</strong>.</li><li>For <strong>Flat Rate Shipping</strong>, enter the <strong>Rate</strong> and choose the <strong>Type</strong>.</li><li>Click <strong>Save Configuration</strong>.</li></ol>',4)),h(o,{src:"/images/configure/shipping-methods-settings.png",alt:"Shipping Methods screen with Free Shipping and Flat Rate Shipping turned on"}),t[1]||(t[1]=e('<p>To stop offering a method, switch its <strong>Status</strong> off and save. All settings are set per channel, and the title and description are also set per language.</p><h2 id="free-shipping" tabindex="-1">Free shipping <a class="header-anchor" href="#free-shipping" aria-label="Permalink to &quot;Free shipping&quot;">​</a></h2><p>A shipping method with no charge.</p><table tabindex="0"><thead><tr><th>Setting</th><th>What it does</th></tr></thead><tbody><tr><td><strong>Title</strong></td><td>The name of the method at checkout, such as <code>Free Shipping</code>. Required while <strong>Status</strong> is on.</td></tr><tr><td><strong>Description</strong></td><td>A short line shown with the method at checkout.</td></tr><tr><td><strong>Status</strong></td><td>Offers the method at checkout.</td></tr></tbody></table><h2 id="flat-rate-shipping" tabindex="-1">Flat rate shipping <a class="header-anchor" href="#flat-rate-shipping" aria-label="Permalink to &quot;Flat rate shipping&quot;">​</a></h2><p>A shipping method that charges a fixed rate.</p><table tabindex="0"><thead><tr><th>Setting</th><th>What it does</th></tr></thead><tbody><tr><td><strong>Title</strong></td><td>The name of the method at checkout, such as <code>Flat Rate</code>. Required while <strong>Status</strong> is on.</td></tr><tr><td><strong>Description</strong></td><td>A short line shown with the method at checkout.</td></tr><tr><td><strong>Rate</strong></td><td>The amount charged, in your store&#39;s base currency. Required while <strong>Status</strong> is on.</td></tr><tr><td><strong>Type</strong></td><td><strong>Per Unit</strong> charges the rate for every unit of each physical product in the cart, so three units cost three times the rate. <strong>Per Order</strong> charges the rate once for the whole order.</td></tr><tr><td><strong>Status</strong></td><td>Offers the method at checkout.</td></tr></tbody></table><p>The address orders are shipped from is set under <a href="./../configure/shipping.html">Shipping Settings</a>.</p>',8))])}const _=r(a,[["render",d]]);export{f as __pageData,_ as default};
